/**
 * t(key, args, lang) — translate. lang 'en' | 'ar' (default 'en').
 * Every interpolated call must be given its args; a header that reuses a
 * per-cell '{n} …' template must not print the brace token.
 */
export function t(key, args, lang = 'en') {
  const entry = I18N_RAW[key];
  if (!entry) return key;
  let s = lang === 'ar' ? entry[1] : entry[0];
  if (args) {
    for (const k of Object.keys(args)) {
      s = s.split('{' + k + '}').join(String(args[k]));
    }
  }
  return s;
}

/**
 * nm(obj, field, lang) — bilingual field read. Arabic primary, English
 * fallback: obj[field + '_ar'] || obj[field + '_en'].
 */
export function nm(obj, field) {
  if (!obj) return '';
  return obj[field + '_ar'] || obj[field + '_en'] || '';
}
